/* parse_ini_string.js, ~ ini reader, authored by 9r3i, https://github.com/9r3i, started at november 18th 2017*/;function parse_ini_string(data){if(typeof data!=="string"){return;}var ex=data.split(/\r\n|\r|\n/g);var res={},store='',index='',pin='';for(var i in ex){if(ex[i]==''&&index==''){continue;}else if(ex[i].match(/^;/g)){continue;}else if(ex[i].match(/^\[(.*)\]/ig)){pin=ex[i].replace(/^\[/ig,'').replace(/\]\s*$/ig,'');res[pin]={};}else if(ex[i].match(/^.+=\s*/ig)&&index==''){var mt=ex[i].match(/^(.+)=\s*"(.*)"\s*$/ig);var mi=ex[i].match(/^[^=]+/ig);if(mt&&mi){index=mi[0].replace(/^\s+|\s+$/ig,'');res[pin][index]=mt[0].substr(mi[0].length).replace(/^\s*=\s*"|\s*"\s*$/ig,'');index='';continue;}var exi=ex[i].match(/^.+=\s*/ig);if(mi){index=mi[0].replace(/^\s+|\s+$/ig,'');}else{index=exi[0].replace(/=\s*$/ig,'').replace(/^\s+|\s+$/ig,'');}exi=ex[i].replace(/^.+=\s*/ig,'');if(exi.match(/^".*"\s*$/ig)){res[pin][index]=exi.substr(1).replace(/"\s*$/ig,'');index='';}else if(exi.match(/^"/ig)){store=exi.substr(1)+'\r\n';}else{res[pin][index]=exi.replace(/^\s+|\s+$/ig,'');index='';}exi=null;}else if(ex[i].match(/"\s*$/ig)&&index!==''){store+=ex[i].replace(/"\s*$/ig,'')+'\r\n';res[pin][index]=store;store='',index='';}else if(index!==''){store+=ex[i]+'\r\n';}}return res;}